namespace MarvinsAIRARefactored.Classes;

// The 68 packet handshake a Logitech Trueforce wheel expects before it will accept a haptic stream on
// its Trueforce endpoint.
//
// These are not composed values, they are the packets Logitech's own G HUB sends, recorded off the wire.
// They were first published in mescon's logitech-rs50-linux-driver (userspace/libtrueforce), which is
// where this table comes from and who deserves the credit for capturing it.
//
// Byte 5 of each packet is the sequence counter and is left zero here; the sender fills it in, counting
// from 1, and the whole sequence is sent twice back to back because cold-booted wheels ignore one pass.

public static class LogitechTrueforceInitData
{
	public const int PacketLength = 64;
	public const int SequenceByteOffset = 5;

	// Index of the two packets that are not part of the handshake proper: the wheel's stop and start
	// commands, sent on their own to park the motor and wake it again.
	public const int StopCommandIndex = 66;
	public const int StartCommandIndex = 67;

	private static readonly string[] _packetsHex =
	[
